//! A short CSS selector that finds one element again, and only it: what
//! auto-extraction reports as a field's source, and what a person copies
//! to pin that field.

use crate::query::Query;
use crate::{Node, NodeKind};

/// The selector for `node`, or None when it isn't an element. It prefers
/// an id, then classes, then the tag, and adds `:nth-of-type()` only when
/// nothing else tells the element from its siblings. Ids and classes that
/// look generated by a build (`ember1234`, `css-1x2y3z`) are passed over,
/// since they change from one deploy to the next.
pub fn css_path(node: Node<'_>) -> Option<String> {
    if node.kind() != NodeKind::Element {
        return None;
    }
    let top = std::iter::successors(Some(node), |n| n.parent())
        .last()
        .unwrap_or(node);
    let mut segments: Vec<String> = Vec::new();
    let mut at = node;
    loop {
        segments.insert(0, segment(at));
        let path = segments.join(" > ");
        if finds_only(&path, top, node) {
            return Some(path);
        }
        match at.parent() {
            Some(p) if p.kind() == NodeKind::Element => at = p,
            // Every segment tells its element from its siblings, so the
            // path from the root element finds only `node`.
            _ => return Some(path),
        }
    }
}

fn finds_only(path: &str, top: Node<'_>, node: Node<'_>) -> bool {
    Query::cached(path).is_ok_and(|q| q.select(top) == [node])
}

/// How to write `node` so that none of its siblings matches: its id when
/// that is unique in the document, else its tag with the fewest stable
/// classes that do it, else its tag, else its tag and position.
fn segment(node: Node<'_>) -> String {
    let tag = escape(node.tag().unwrap_or("*"));
    if let Some(id) = node
        .attr("id")
        .filter(|id| !id.is_empty() && !generated(id))
    {
        let by_id = format!("#{}", escape(id));
        let top = std::iter::successors(Some(node), |n| n.parent())
            .last()
            .unwrap_or(node);
        if finds_only(&by_id, top, node) {
            return by_id;
        }
    }
    let siblings: Vec<Node<'_>> = node
        .parent()
        .map(|p| {
            p.children()
                .filter(|s| s.kind() == NodeKind::Element && *s != node && s.tag() == node.tag())
                .collect()
        })
        .unwrap_or_default();
    if siblings.is_empty() {
        return tag;
    }
    let classes: Vec<&str> = node
        .attr("class")
        .unwrap_or_default()
        .split_ascii_whitespace()
        .filter(|c| !generated(c))
        .collect();
    let has = |s: &Node<'_>, wanted: &[&str]| {
        let theirs: Vec<&str> = s
            .attr("class")
            .unwrap_or_default()
            .split_ascii_whitespace()
            .collect();
        wanted.iter().all(|c| theirs.contains(c))
    };
    for &c in &classes {
        if !siblings.iter().any(|s| has(s, &[c])) {
            return format!("{tag}.{}", escape(c));
        }
    }
    for (i, &a) in classes.iter().enumerate() {
        for &b in &classes[i + 1..] {
            if !siblings.iter().any(|s| has(s, &[a, b])) {
                return format!("{tag}.{}.{}", escape(a), escape(b));
            }
        }
    }
    let position = node
        .parent()
        .map(|p| {
            p.children()
                .filter(|s| s.kind() == NodeKind::Element && s.tag() == node.tag())
                .position(|s| s == node)
                .unwrap_or(0)
        })
        .unwrap_or(0);
    format!("{tag}:nth-of-type({})", position + 1)
}

/// Whether an id or class looks made by a build tool rather than a
/// person: a run of three digits, or a part (between `-` and `_`) of four
/// or more characters mixing letters and digits, as hashes do.
fn generated(name: &str) -> bool {
    let mut digits = 0;
    for c in name.chars() {
        digits = if c.is_ascii_digit() { digits + 1 } else { 0 };
        if digits >= 3 {
            return true;
        }
    }
    name.split(['-', '_']).any(|part| {
        part.len() >= 4
            && part.chars().any(|c| c.is_ascii_digit())
            && part.chars().any(|c| c.is_ascii_alphabetic())
    })
}

/// `name` as a CSS identifier, escaped as CSSOM's `CSS.escape` does.
fn escape(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for (i, c) in name.chars().enumerate() {
        let first = i == 0;
        match c {
            '\0' => out.push('\u{FFFD}'),
            '\u{1}'..='\u{1F}' | '\u{7F}' => out.push_str(&format!("\\{:x} ", c as u32)),
            '0'..='9' if first => out.push_str(&format!("\\{:x} ", c as u32)),
            '0'..='9' if i == 1 && name.starts_with('-') => {
                out.push_str(&format!("\\{:x} ", c as u32))
            }
            '-' if first && name.len() == 1 => out.push_str("\\-"),
            c if c.is_ascii_alphanumeric() || c == '-' || c == '_' || !c.is_ascii() => out.push(c),
            c => {
                out.push('\\');
                out.push(c);
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_names_are_told_from_written_ones() {
        for name in ["ember1234", "css-1x2y3z", "jsx-8f9a", "sc-a1b2c3"] {
            assert!(generated(name), "{name}");
        }
        for name in [
            "lead",
            "col-md-6",
            "h2",
            "product-title",
            "mt-4",
            "price_now",
        ] {
            assert!(!generated(name), "{name}");
        }
    }

    #[test]
    fn escaping_follows_css_escape() {
        assert_eq!(escape("a:b.c"), r"a\:b\.c");
        assert_eq!(escape("9lives"), r"\39 lives");
        assert_eq!(escape("-9"), r"-\39 ");
        assert_eq!(escape("-"), r"\-");
        assert_eq!(escape("w-1/2"), r"w-1\/2");
    }
}
